  "Les modifications s'appliquent au match en cours et aux suivants. Les matchs archivés gardent leur effectif d'origine. La limite de 14 porte sur les sélections pour un match, pas sur l'effectif.": "Changes apply to the current and future matches. Archived matches keep their original roster. The limit of 14 applies to players selected for a match, not to the roster.",
