  "Toile : part des passes vers chaque poste, bord = poste le plus servi (indice 100), échelle racine carrée, filet en haut. Réussite : - = 0, = = 1, + = 2 ; vert / rouge : 10 points au-dessus / en dessous de la moyenne de la passe.": "Web: share of sets to each position, edge = most-used position (index 100), net at the top. Success: - = 0, = = 1, + = 2; green / red: 10 points above / below the setter's average.",
  "Toile et chiffres : vert / rouge = 10 points au-dessus / en dessous de l'équipe. Barres : vert = efficacité, rouge = fautes, trait foncé = niveau de l'équipe. En gris : moins de 5 ballons ou moins de 5 % du temps.": "Web and figures: green / red = 10 points above / below the team. Bars: green = efficiency, red = errors, dark line = team level. Greyed: fewer than 5 balls or under 5 % of the time.",
  "Erreurs d'attaque : attaque - ou renvoi sans attaque sur une passe + ou =": "Attack errors: attack - or free ball on a set + or =",
