  "Placement quand {N} sert (et zones des statistiques) : libéro et centre arrière défendent à ce poste, R4 arrière à l'autre.": "Placement when {N} serves (and statistics zones): the libero and the back-row middle defend in this position, the back-row OH in the other.",
  "Le changement de libéro n'est pas compté comme un remplacement. Poste 5 / Poste 6 : place du libéro en défense quand {N} sert.": "A libero change does not count as a substitution. Position 5 / Position 6: where the libero defends when {N} serves.",
