  "Placement quand {N} sert (et zones des statistiques) : libéro et centre arrière défendent à ce poste, R4 arrière à l'autre.": "Colocación cuando {N} saca (y zonas de las estadísticas): líbero y la central zaguera defienden en esta zona, la receptor zaguera en la otra.",
  "Le changement de libéro n'est pas compté comme un remplacement. Poste 5 / Poste 6 : place du libéro en défense quand {N} sert.": "El cambio de líbero no cuenta como sustitución. Posición 5 / 6: zona de defensa del líbero cuando {N} saca.",
