  "Valable jusqu’au {N}, sans renouvellement automatique.": "Válido hasta el {N}, sin renovación automática.",
  "Je demande l’accès immédiat aux fonctions Pro et je renonce à mon droit de rétractation dès le début du service.": "Solicito el acceso inmediato a las funciones Pro y renuncio a mi derecho de desistimiento desde el inicio del servicio.",
