  "Point vert / rouge : efficacité à 10 points au-dessus / en dessous de la moyenne (3 actions minimum).": "Punto verde / rosso: efficacia 10 punti sopra / sotto la media (minimo 3 azioni).",
  "Mode stats faciles": "Modalità statistiche facili",
