  "Le match en cours est archivé dans la saison en cours, puis une nouvelle feuille de match s'ouvre avec les mêmes présences et postes.": "Bieżący mecz trafia do archiwum bieżącego sezonu, potem otwiera się nowy protokół z tymi samymi obecnościami i pozycjami.",
