  "14 au maximum, hors feuille compris. Une personne à deux maillots ne compte qu'une fois.": "Maksymalnie 14, łącznie z osobami spoza protokołu. Osoba z dwiema koszulkami liczy się raz.",
  "Protéger le Menu par un code": "Chroń strefę trenera kodem",
  "Menu": "Menu",
  "Le pass sera en vente à partir du 1er septembre 2027. D’ici là, toutes les fonctions sont gratuites.": "Karnet będzie w sprzedaży od 1 września 2027 r. Do tego czasu wszystkie funkcje są bezpłatne.",
  "Pass saison": "Karnet sezonowy",
  "Valable jusqu’au {N}, sans renouvellement automatique.": "Ważny do {N}, bez automatycznego odnowienia.",
  "Je demande l’accès immédiat aux fonctions Pro et je renonce à mon droit de rétractation dès le début du service.": "Żądam natychmiastowego dostępu do funkcji Pro i rezygnuję z prawa odstąpienia od umowy z chwilą rozpoczęcia usługi.",
  "Achat en cours…": "Trwa zakup…",
  "Acheter le pass": "Kup karnet",
  "Cochez la case pour acheter.": "Zaznacz pole, aby kupić.",
  "Restaurer mes achats": "Przywróć zakupy",
  "✓ Pass saison actif jusqu’au {N}.": "✓ Karnet sezonowy aktywny do {N}.",
  "✓ Pass saison actif.": "✓ Karnet sezonowy aktywny.",
  "Le pass est valable de la date d’achat au 31 août qui suit : 29,99 € de septembre à décembre, 19,99 € à partir du 1er janvier. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "Karnet jest ważny od daty zakupu do najbliższego 31 sierpnia: 29,99 € od września do grudnia, 19,99 € od 1 stycznia. Zakup w App Store lub Google Play, dla urządzeń z tym samym kontem.",
  "Paiement en attente : le pass sera activé dès sa confirmation par le store": "Płatność oczekuje: karnet zostanie aktywowany po potwierdzeniu przez sklep",
  "Pass déjà acheté : il est restauré": "Karnet już kupiony: został przywrócony",
  "Pass déjà acheté, mais introuvable : touchez « Restaurer mes achats »": "Karnet już kupiony, ale nie znaleziono go: dotknij „Przywróć zakupy”",
  "Achat indisponible : vérifiez la connexion et le compte du store": "Zakup niedostępny: sprawdź połączenie i konto sklepu",
  "Achat impossible, réessayez plus tard": "Zakup nie powiódł się, spróbuj później",
  "Pass restauré": "Karnet przywrócony",
  "Aucun pass trouvé pour ce compte": "Nie znaleziono karnetu dla tego konta",
  "Store injoignable : vérifiez la connexion": "Sklep niedostępny: sprawdź połączenie",
  "VolleyCoach Pro activé": "VolleyCoach Pro aktywowany",
  "Pass mi-saison": "Karnet na pół sezonu",
  "En vente jusqu’au {N}": "W sprzedaży do {N}",
  "En vente à partir du {N}": "W sprzedaży od {N}",
  "Hors période de vente": "Poza okresem sprzedaży",
  "Acheter ce pass": "Kup ten karnet",
  "Deux pass, valables jusqu’au 31 août : le pass saison (29,99 €), en vente de septembre à décembre, et le pass mi-saison (19,99 €), en vente de janvier à août. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "Dwa karnety, oba ważne do 31 sierpnia: karnet sezonowy (29,99 €), w sprzedaży od września do grudnia, i karnet na pół sezonu (19,99 €), w sprzedaży od stycznia do sierpnia. Zakup w App Store lub Google Play, dla urządzeń z tym samym kontem.",
  "Essai gratuit en cours : {N} jours restants.": "Trwa bezpłatny okres próbny: zostało {N} dni.",
  "Version gratuite : seuls le passeur, un R4 et un central sont classés.": "Wersja bezpłatna: w rankingach tylko rozgrywający, jeden R4 i jeden środkowy.",
  "Version gratuite : stats du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "Wersja bezpłatna: statystyki rozgrywającego, jednego R4 i jednego środkowego (najczęściej grających na swojej pozycji).",
  "Stats de tous les joueurs (le gratuit analyse le passeur, un R4 et un central)": "Statystyki wszystkich osób (wersja bezpłatna analizuje rozgrywającego, jednego R4 i jednego środkowego)",
  "Version gratuite : saisie des matchs, résumés de match (PDF compris), sauvegarde complète, stats et classement du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "Wersja bezpłatna: zapis meczów, podsumowania meczów (z PDF), pełna kopia zapasowa, statystyki i ranking rozgrywającego, jednego R4 i jednego środkowego (najczęściej grających na swojej pozycji).",
  "Statistiques supplémentaires": "Dodatkowe statystyki",
