  "Point vert / rouge : efficacité à 10 points au-dessus / en dessous de la moyenne (3 actions minimum).": "Ponto verde / vermelho: eficiência 10 pontos acima / abaixo da média (mínimo 3 ações).",
  "Mode stats faciles": "Modo estatísticas fáceis",
  "Activer le mode stats faciles": "Ativar o modo fácil",
  "Banc vide.": "Banco vazio.",
  "Saisie des stats facilitée, gestion d'équipe un peu plus lente : pendant le match, les stats occupent tout l'écran (le score reste visible et cliquable). Un appui sur « Revenir au terrain » ou « Stats de l'échange » passe de l'un à l'autre.": "Registro de estatísticas facilitado, gestão da equipe um pouco mais lenta: durante o jogo as estatísticas ocupam toda a tela (o placar continua visível e clicável).",
  "Relais de passe": "Levantamento de apoio",
  "Bloquer la rotation de l’écran": "Bloquear rotação da tela",
  "Fautes directes": "Erros diretos",
  "Un point par match (3 actions minimum). Flèche : tendance sur la saison (▲ en progrès, ▼ en baisse). À gauche : valeur au premier match ; sur la courbe : minimum en rouge, maximum en vert, courbe jaune = tendance lissée sur 3 matchs ; à droite : tendance de la saison pondérée par le nombre d'actions (« stable » si moins de 5 points). Valeur ajoutée : ligne pointillée = 0 pt.": "Um ponto por jogo (mínimo 3 ações). Seta: tendência da temporada (▲ em alta, ▼ em baixa). Sob cada curva: diferença entre o primeiro e o último jogo, mínimo (círculo vermelho) e máximo (círculo verde). Fatores: linha pontilhada = 0 %.",
  "1er → dernier": "Primeiro → último",
  "Niveau": "Nível",
  "Jeunes": "Base",
  "Régional": "Regional",
  "National": "Nacional",
  "Le niveau fixe la référence de la valeur ajoutée (note attendue d'une passe ou d'une attaque selon la qualité du ballon reçu).": "O nível define a referência do valor agregado (nota esperada de um levantamento ou ataque conforme a bola recebida).",
