  "Surface bleue = part des ballons joués au poste": "Mavi alan = bölgede oynanan top payı",
  "(bord = poste le plus servi, indice 100)": "(kenar = en çok kullanılan bölge, endeks 100)",
  "Trait vert = efficacité au poste": "Yeşil çizgi = bölgedeki verimlilik",
  "(centre 0 %, bord 100 %)": "(merkez %0, kenar %100)",
  "Classements par efficacité": "Verimliliğe göre sıralamalar",
  "Classement par efficacité, puis par nombre d'actions. Efficacité = points / maximum, avec action + = 2 points, = = 1 point, - = 0. Service non noté = neutre ; réceptions non notées non comptées.": "Önce verimliliğe, sonra eylem sayısına göre sıralama. Verimlilik = puan / maksimum, + = 2 puan, = = 1 puan, - = 0. Kaydedilmemiş servis = nötr; kaydedilmemiş karşılamalar sayılmaz.",
