  "Acheter ce pass": "Bu kartı satın al",
  "Deux pass, valables jusqu’au 31 août : le pass saison (29,99 €), en vente de septembre à décembre, et le pass mi-saison (19,99 €), en vente de janvier à août. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "İki kart, ikisi de 31 Ağustos'a kadar geçerli: Eylül–Aralık arası satılan sezon kartı (29,99 €) ve Ocak–Ağustos arası satılan yarım sezon kartı (19,99 €). App Store veya Google Play'den satın alınır, aynı hesabı kullanan cihazlarda geçerlidir.",
  "Essai gratuit en cours : {N} jours restants.": "Ücretsiz deneme sürüyor: {N} gün kaldı.",
  "Version gratuite : seuls le passeur, un R4 et un central sont classés.": "Ücretsiz sürüm: sıralamalarda yalnızca pasör, bir R4 ve bir orta oyuncu yer alır.",
  "Version gratuite : stats du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "Ücretsiz sürüm: pasörün, bir R4'ün ve bir orta oyuncunun istatistikleri (mevkisinde en çok oynayanlar).",
  "Stats de tous les joueurs (le gratuit analyse le passeur, un R4 et un central)": "Tüm oyuncuların istatistikleri (ücretsiz sürüm pasörü, bir R4'ü ve bir orta oyuncuyu analiz eder)",
  "Version gratuite : saisie des matchs, résumés de match (PDF compris), sauvegarde complète, stats et classement du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "Ücretsiz sürüm: maç kaydı, maç özetleri (PDF dahil), tam yedekleme, pasörün, bir R4'ün ve bir orta oyuncunun istatistikleri ve sıralaması (mevkisinde en çok oynayanlar).",
