  "14 au maximum, hors feuille compris. Une personne à deux maillots ne compte qu'une fois.": "最大14人（登録外の選手を含む）。背番号が2つある選手は1人として数えます。",
  "Menu": "メニュー",
  "Le pass sera en vente à partir du 1er septembre 2027. D’ici là, toutes les fonctions sont gratuites.": "シーズンパスは2027年9月1日に発売されます。それまではすべての機能を無料でご利用いただけます。",
  "Pass saison": "シーズンパス",
  "Valable jusqu’au {N}, sans renouvellement automatique.": "{N}まで有効、自動更新なし。",
  "Je demande l’accès immédiat aux fonctions Pro et je renonce à mon droit de rétractation dès le début du service.": "Pro機能への即時アクセスを希望し、サービス開始時点で撤回権を放棄します。",
  "Achat en cours…": "購入処理中…",
