  "✓ Pass saison actif jusqu’au {N}.": "✓ シーズンパス有効（{N}まで）。",
  "✓ Pass saison actif.": "✓ シーズンパス有効。",
  "Le pass est valable de la date d’achat au 31 août qui suit : 29,99 € de septembre à décembre, 19,99 € à partir du 1er janvier. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "パスは購入日から次の8月31日まで有効です。9月〜12月は29.99ユーロ、1月1日以降は19.99ユーロ。App StoreまたはGoogle Playで購入し、同じアカウントの端末で利用できます。",
  "Paiement en attente : le pass sera activé dès sa confirmation par le store": "支払い保留中：ストアの確認後にパスが有効になります",
  "Pass déjà acheté : il est restauré": "購入済みのパスを復元しました",
  "Pass déjà acheté, mais introuvable : touchez « Restaurer mes achats »": "購入済みですが見つかりません：「購入を復元」をタップしてください",
  "Achat indisponible : vérifiez la connexion et le compte du store": "購入できません：接続とストアのアカウントを確認してください",
