  "Store injoignable : vérifiez la connexion": "ストアに接続できません：接続を確認してください",
  "VolleyCoach Pro activé": "VolleyCoach Pro を有効にしました",
  "Pass mi-saison": "ハーフシーズンパス",
  "En vente jusqu’au {N}": "{N}まで販売",
  "En vente à partir du {N}": "{N}から販売",
  "Hors période de vente": "販売期間外",
  "Acheter ce pass": "このパスを購入",
  "Deux pass, valables jusqu’au 31 août : le pass saison (29,99 €), en vente de septembre à décembre, et le pass mi-saison (19,99 €), en vente de janvier à août. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "パスは2種類で、どちらも8月31日まで有効です。シーズンパス（29.99ユーロ）は9月〜12月、ハーフシーズンパス（19.99ユーロ）は1月〜8月に販売します。App StoreまたはGoogle Playで購入し、同じアカウントの端末で利用できます。",
  "Essai gratuit en cours : {N} jours restants.": "無料トライアル中：残り{N}日。",
  "Version gratuite : seuls le passeur, un R4 et un central sont classés.": "無料版：ランキングはセッター、R4 1人、ミドル1人のみ。",
  "Version gratuite : stats du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "無料版：セッター、R4 1人、ミドル1人（各ポジションで最も出場した選手）の統計。",
  "Stats de tous les joueurs (le gratuit analyse le passeur, un R4 et un central)": "全選手の統計（無料版はセッター、R4 1人、ミドル1人を分析）",
  "Version gratuite : saisie des matchs, résumés de match (PDF compris), sauvegarde complète, stats et classement du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "無料版：試合の記録、試合サマリー（PDFを含む）、完全バックアップ、セッター・R4 1人・ミドル1人（各ポジションで最も出場した選手）の統計とランキング。",
  "Statistiques supplémentaires": "追加の統計",
  "Notées pendant le match, en plus des actions de base.": "基本プレーに加えて試合中に記録します。",
  "Un chapitre par sujet ; chacun se termine ici.": "テーマごとに1章。各章はここで終わります。"
