  "✓ Pass saison actif jusqu’au {N}.": "✓ บัตรฤดูกาลใช้ได้ถึง {N}",
  "✓ Pass saison actif.": "✓ บัตรฤดูกาลใช้งานอยู่",
  "Le pass est valable de la date d’achat au 31 août qui suit : 29,99 € de septembre à décembre, 19,99 € à partir du 1er janvier. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "บัตรใช้ได้ตั้งแต่วันที่ซื้อจนถึงวันที่ 31 สิงหาคมถัดไป: 29.99 € ตั้งแต่กันยายนถึงธันวาคม และ 19.99 € ตั้งแต่ 1 มกราคม ซื้อผ่าน App Store หรือ Google Play สำหรับอุปกรณ์ที่ใช้บัญชีเดียวกัน",
  "Paiement en attente : le pass sera activé dès sa confirmation par le store": "รอการชำระเงิน: บัตรจะเปิดใช้งานเมื่อสโตร์ยืนยัน",
