  "Menu": "메뉴",
  "Le pass sera en vente à partir du 1er septembre 2027. D’ici là, toutes les fonctions sont gratuites.": "시즌 패스는 2027년 9월 1일부터 판매됩니다. 그 전까지는 모든 기능이 무료입니다.",
