  "✓ Pass saison actif jusqu’au {N}.": "✓ 시즌 패스 {N}까지 유효.",
  "✓ Pass saison actif.": "✓ 시즌 패스 사용 중.",
  "Le pass est valable de la date d’achat au 31 août qui suit : 29,99 € de septembre à décembre, 19,99 € à partir du 1er janvier. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "패스는 구매일부터 다음 8월 31일까지 유효합니다. 9월~12월은 29.99유로, 1월 1일부터는 19.99유로입니다. App Store 또는 Google Play에서 구매하며, 같은 계정의 기기에서 사용할 수 있습니다.",
  "Paiement en attente : le pass sera activé dès sa confirmation par le store": "결제 대기 중: 스토어에서 확인되면 패스가 활성화됩니다",
  "Pass déjà acheté : il est restauré": "이미 구매한 패스를 복원했습니다",
  "Pass déjà acheté, mais introuvable : touchez « Restaurer mes achats »": "이미 구매했지만 찾을 수 없습니다: ‘구매 복원’을 누르세요",
  "Achat indisponible : vérifiez la connexion et le compte du store": "구매할 수 없습니다: 연결과 스토어 계정을 확인하세요",
  "Achat impossible, réessayez plus tard": "구매에 실패했습니다. 나중에 다시 시도하세요",
  "Pass restauré": "패스가 복원되었습니다",
  "Aucun pass trouvé pour ce compte": "이 계정에서 패스를 찾을 수 없습니다",
  "Store injoignable : vérifiez la connexion": "스토어에 연결할 수 없습니다: 연결을 확인하세요",
  "VolleyCoach Pro activé": "VolleyCoach Pro가 활성화되었습니다",
  "Pass mi-saison": "하프 시즌 패스",
  "En vente jusqu’au {N}": "{N}까지 판매",
  "En vente à partir du {N}": "{N}부터 판매",
