  "Acheter ce pass": "이 패스 구매",
  "Deux pass, valables jusqu’au 31 août : le pass saison (29,99 €), en vente de septembre à décembre, et le pass mi-saison (19,99 €), en vente de janvier à août. Achat dans l’App Store ou Google Play, sur les appareils du même compte.": "두 가지 패스 모두 8월 31일까지 유효합니다. 시즌 패스(29.99유로)는 9월~12월, 하프 시즌 패스(19.99유로)는 1월~8월에 판매합니다. App Store 또는 Google Play에서 구매하며, 같은 계정의 기기에서 사용할 수 있습니다.",
  "Essai gratuit en cours : {N} jours restants.": "무료 체험 중: {N}일 남음.",
  "Version gratuite : seuls le passeur, un R4 et un central sont classés.": "무료 버전: 순위에는 세터, R4 1명, 미들 블로커 1명만 포함됩니다.",
  "Version gratuite : stats du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "무료 버전: 세터, R4 1명, 미들 블로커 1명(각 포지션에서 가장 많이 뛴 선수)의 통계.",
  "Stats de tous les joueurs (le gratuit analyse le passeur, un R4 et un central)": "모든 선수의 통계(무료 버전은 세터, R4 1명, 미들 블로커 1명을 분석)",
  "Version gratuite : saisie des matchs, résumés de match (PDF compris), sauvegarde complète, stats et classement du passeur, d’un R4 et d’un central (les plus utilisés à leur poste).": "무료 버전: 경기 기록, 경기 요약(PDF 포함), 전체 백업, 세터·R4 1명·미들 블로커 1명(각 포지션에서 가장 많이 뛴 선수)의 통계와 순위.",
